'use client';

import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { useRouter } from 'next/navigation';
import { AlertTriangle, ArrowLeft, ArrowRight, BadgeCheck, Car, CheckCircle2, Clock3, RefreshCcw, Search, ShieldCheck, Signal, SignalZero, Trash2, UserRoundPlus } from 'lucide-react';
import { addFilterStudents, createExtraordinaryHandoff, searchFilterReporters, searchFilterStudents } from '@/lib/actions/filter-control';
import { clearExtraordinaryHandoffDraft, ExtraordinaryHandoffDraft, getExtraordinaryHandoffDraft, PersistedFile, persistFile, restoreFileForUpload, saveExtraordinaryHandoffDraft } from '@/lib/filter-early-departure-draft';
import { useToast } from '@/hooks/use-toast';
import { Alert, AlertDescription, AlertTitle } from '@/components/ui/alert';
